Position startSize=main.Size end end)UserInputService.InputChanged:Connect(function(i)if i.UserInputType==Enum.MouseMovement then if dragging then local delta=i.Position-dragStart main.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset+delta.X,startPos.Y.Scale,startPos.Y.Offset+delta.Y)elseif draggingRes then local delta=i.Position-dragStart main.Size=UDim2.new(0,math.max(150,startSize.X.Offset+delta.X),0,math.max(100,startSize.Y.Offset+delta.Y))end end end)UserInputService.InputEnded:Connect(function(i)if i.UserInputType==Enum.UserInputType.MouseButton1 then dragging=false draggingRes=false end end)local function updateGraph(s)local maxHeight=150 local targetY=maxHeight-math.clamp(s^EXPONENT*INTENSITY,5,maxHeight-5)local prevY=maxHeight-math.clamp(lastSpeed^EXPONENT*INTENSITY,5,maxHeight-5)local line=Instance.new("Frame",graphContainer)line.BorderSizePixel=0 line.BackgroundColor3=Color3.fromRGB(255,105,180)local diff=targetY-prevY line.Size=UDim2.new(0,SCROLL_SPEED+0.5,0,math.abs(diff)+1.5)line.Position=UDim2.new(0,548,0,math.min(targetY,prevY))table.insert(segments,line)if#segments>180 then segments[1]:Destroy()table.remove(segments,1)end for i=1,#segments do segments[i].Position=segments[i].Position-UDim2.new(0,SCROLL_SPEED,0,0)end lastSpeed=s end UserInputService.InputBegan:Connect(function(input,gpe)if gpe then return end local k=input.KeyCode if k==binds.toggleGui then guiVisible=not guiVisible main.Visible=guiVisible graphContainer.Visible=guiVisible indContainer.Visible=guiVisible velText.Visible=guiVisible elseif k==binds.eb then slideActive=true elseif k==binds.jb then jumpbugActive=true elseif k==binds.px then pixelsurfActive=true if player.Character and player.Character:FindFirstChild("HumanoidRootPart")then lockedY=player.Character.HumanoidRootPart.Position.Y end elseif k==binds.as then airstuckActive=not airstuckActive if airstuckActive and player.Character and player.Character:FindFirstChild("HumanoidRootPart")then airstuckPos=player.Character.HumanoidRootPart.CFrame else airstuckPos=nil end elseif k==binds.lj then longjumpActive=true elseif k==binds.bhop then bhopActive=not bhopActive elseif k==binds.ns then noSpreadActive=not noSpreadActive if WeaponsFolder then for _,weapon in ipairs(WeaponsFolder:GetChildren())do noSpread(weapon)end end elseif k==Enum.KeyCode.W then keysPressed.W=true elseif k==Enum.KeyCode.A then keysPressed.A=true elseif k==Enum.KeyCode.S then keysPressed.S=true elseif k==Enum.KeyCode.D then keysPressed.D=true end end)UserInputService.InputEnded:Connect(function(input)local k=input.KeyCode if k==binds.eb then slideActive=false elseif k==binds.jb then jumpbugActive=false elseif k==binds.px then pixelsurfActive=false lockedY=nil elseif k==binds.lj then longjumpActive=false elseif k==Enum.KeyCode.W then keysPressed.W=false elseif k==Enum.KeyCode.A then keysPressed.A=false elseif k==Enum.KeyCode.S then keysPressed.S=false elseif k==Enum.KeyCode.D then keysPressed.D=false end end)RunService.Heartbeat:Connect(function(dt)local char=player.Character if not char then return end local root=char:FindFirstChild("HumanoidRootPart")local hum=char:FindFirstChild("Humanoid")if not root or not hum then return end if hum.WalkSpeed~=20 then hum.WalkSpeed=20 end local hVel=Vector3.new(root.Velocity.X,0,root.Velocity.Z)local hSpeed=hVel.Magnitude lastUpdate=lastUpdate+dt if lastUpdate>=0.033 then lastUpdate=0 if guiVisible then velText.Text=string.format("%.2f",hSpeed)updateGraph(hSpeed)local states={eb=slideActive,jb=jumpbugActive,px=pixelsurfActive,lj=longjumpActive,as=airstuckActive,bh=bhopActive,ns=noSpreadActive,ws=true}for id,active in pairs(states)do if inds[id]then inds[id].Label.TextTransparency=active and 0 or 1 inds[id].Stroke.Transparency=active and 0 or 1 end end end end if airstuckActive and airstuckPos then root.CFrame=airstuckPos root.Velocity=Vector3.zero return end local onGround=hum.FloorMaterial~=Enum.Material.Air local now=tick()if bhopActive then if UserInputService:IsKeyDown(Enum.KeyCode.Space)and onGround then hum.Jump=true if keysPressed.W then local look=root.CFrame.LookVector root.Velocity=Vector3.new(look.X*BHOP_LOCK_SPEED,root.Velocity.Y,look.Z*BHOP_LOCK_SPEED)end elseif not onGround then if hSpeed>BHOP_LOCK_SPEED then local capped=hVel.Unit*BHOP_LOCK_SPEED root.Velocity=Vector3.new(capped.X,root.Velocity.Y,capped.Z)end elseif onGround and hSpeed>18 then local newS=math.max(18,hSpeed*DECAY_RATE)root.Velocity=Vector3.new(hVel.Unit.X*newS,root.Velocity.Y,hVel.Unit.Z*newS)end end if onGround and(now-lastJumpTime)>JUMP_COOLDOWN then if longjumpActive then lastJumpTime=now root.Velocity=root.CFrame.LookVector*50+Vector3.new(0,30,0)elseif jumpbugActive then lastJumpTime=now root.Velocity=Vector3.new(root.Velocity.X,33,root.Velocity.Z)end end if slideActive and root.Velocity.Y<-5 then root.Velocity=root.Velocity:Lerp(Vector3.new(root.Velocity.X,FAST_FALL_SPEED,root.Velocity.Z),FALL_LERP)end if slideActive then if not slideBodyVelocity then slideBodyVelocity=Instance.new("BodyVelocity",root)slideBodyVelocity.MaxForce=Vector3.new(1e7,0,1e7)end local camCF=camera.CFrame local moveDir=(Vector3.new(camCF.LookVector.X,0,camCF.LookVector.Z).Unit*(keysPressed.W and 1 or(keysPressed.S and-1 or 0)))+(Vector3.new(camCF.RightVector.X,0,camCF.RightVector.Z).Unit*(keysPressed.D and 1 or(keysPressed.A and-1 or 0)))local targetVel=(moveDir.Magnitude>0 and moveDir.Unit or Vector3.new(camCF.LookVector.X,0,camCF.LookVector.Z).Unit)*LOCKED_SLIDE_SPEED slideCurrentVel=slideCurrentVel:Lerp(targetVel,SMOOTH_FAC)slideBodyVelocity.Velocity=Vector3.new(slideCurrentVel.X,0,slideCurrentVel.Z)elseif slideBodyVelocity then local lastVel=slideCurrentVel slideBodyVelocity:Destroy()slideBodyVelocity=nil slideCurrentVel=Vector3.new(0,0,0)root.Velocity=Vector3.new(lastVel.X,root.Velocity.Y,lastVel.Z)end end if pixelsurfActive and lockedY then local bp=Instance.new("BodyPosition",root)bp.MaxForce=Vector3.new(0,40000,0)bp.Position=Vector3.new(root.Position.X,lockedY,root.Position.Z